def _validate_braces(format):
    """Validate that all braces in the format string are properly matched/escaped.

    Raises ValueError if there are unmatched or improperly nested braces.
    """
    depth = 0
    i = 0
    while i < len(format):
        c = format[i]
        if c == '{':
            # Check if it's an escaped brace {{
            if i + 1 < len(format) and format[i + 1] == '{':
                i += 2  # skip both braces
                continue
            # Unmatched opening brace
            depth += 1
        elif c == '}':
            # Check if it's an escaped brace }}
            if i > 0 and format[i - 1] == '}':
                i += 1  # already handled by previous iteration, skip
                continue
            if depth == 0:
                raise ValueError("unmatched '}' in format string: %r" % format)
            depth -= 1
        i += 1

    if depth != 0:
        raise ValueError("unmatched '{' in format string: %r" % format)


